    let paths = default_marker_paths(git_root);
    clear_markers_at(&paths);
}

pub fn clear_markers_at(paths: &MarkerPaths) {
    let _ = std::fs::remove_file(&paths.done);
    let _ = std::fs::remove_file(&paths.blocked);
}

